class Solution {
public:
    int longestPalindromeSubseq(string s) {
        int n = s.size();
        vector<int> dp(n, 1);
        for (int i = n - 1; i >= 0; --i) {
            int diag = 0;
            for (int j = i + 1; j < n; ++j) {
                int temp = dp[j];
                if (s[i] == s[j]) {
                    dp[j] = diag + 2;
                } else {
                    dp[j] = max(dp[j], dp[j - 1]);
                }
                diag = temp;
            }
        }
        return dp[n - 1];
    }
};

class Solution {
    public int longestPalindromeSubseq(String s) {
        int n = s.length();
        int[] dp = new int[n];
        Arrays.fill(dp, 1);
        for (int i = n - 1; i >= 0; i--) {
            int diag = 0;
            for (int j = i + 1; j < n; j++) {
                int temp = dp[j];
                if (s.charAt(i) == s.charAt(j)) {
                    dp[j] = diag + 2;
                } else {
                    dp[j] = Math.max(dp[j], dp[j - 1]);
                }
                diag = temp;
            }
        }
        return dp[n - 1];
    }
}

var longestPalindromeSubseq = function(s) {
    const n = s.length;
    const dp = new Array(n).fill(1);
    for (let i = n - 1; i >= 0; i--) {
        let diag = 0;
        for (let j = i + 1; j < n; j++) {
            const temp = dp[j];
            if (s[i] === s[j]) {
                dp[j] = diag + 2;
            } else {
                dp[j] = Math.max(dp[j], dp[j - 1]);
            }
            diag = temp;
        }
    }
    return dp[n - 1];
};
